// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        // Bound inputs to avoid overflow or invalid calls
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, 1e18);
        }

        // Record the initial value of 'from'
        address beforeFrom = c.from();

        // Call from the authorized address
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, _tos, v));
        require(success, "transfer reverted");

        // After the call, 'from' must still be the original value (it never changes)
        assertTrue(c.from() == beforeFrom);
    }
}

